INSERT INTO psychiatric_factors (code, name) VALUES
('1', '1. Деятельность, связанная с управлением транспортными средствами или управлением движением транспортных средств по профессиям и должностям согласно перечню работ, профессий, должностей, непосредственно связанных с управлением транспортными средствами или управлением движением транспортных средств.'),
('2', '2. Деятельность, связанная с производством, транспортировкой, хранением и применением взрывчатых материалов и веществ.'),
('3', '3. Деятельность в области использования атомной энергии, осуществляемая работниками объектов использования атомной энергии при наличии у них разрешений, выдаваемых органами Федеральной службы по экологическому, технологическому и атомному надзору'),
('4', '4. Деятельность, связанная с оборотом оружия.'),
('5', '5. Деятельность, связанная с проведением аварийно-спасательных работ, а также с работой, выполняемой пожарной охраной при тушении пожаров.'),
('6', '6. Деятельность, непосредственно связанная с управлением подъемными механизмами (кранами), подлежащими учету в органах Федеральной службы по экологическому, технологическому и атомному надзору.'),
('7', '7. Деятельность по непосредственному забору, очистке и распределению воды питьевых нужд систем централизованного водоснабжения.'),
('8', '8. Педагогическая деятельность в организациях, осуществляющих образовательную деятельность.'),
('9', '9. Деятельность по присмотру и уходу за детьми.'),
('10', '10. Деятельность, связанная с работами с использованием сведений, составляющими государственную тайну.'),
('11', '11. Деятельность в сфере электроэнергетики, связанная с организацией и осуществлением монтажа, наладки, технического обслуживания, ремонта, управления режимом работы электроустановок.'),
('12', '12. Деятельность в сфере теплоснабжения, связанная с организацией и осуществлением монтажа, наладки, технического обслуживания, ремонта, управления режимом работы объектов теплоснабжения.'),
('13', '13. Деятельность, непосредственно связанная с обслуживанием оборудования, работающего под избыточным давлением более 0,07 МПа и подлежащего учету в органах Федеральной службы по экологическому, технологическому и атомному надзору пара, газа (в газообразном, сжиженном состоянии); воды при температуре более 115 °C; иных жидкостей при температуре, превышающей температуру их кипения при избыточном давлении 0,07 МПа.'),
('14', '14. Деятельность, непосредственно связанная с диспетчеризацией производственных процессов в химической (нефтехимической) промышленности, включая деятельность операторов производственного оборудования в химической (нефтехимической) промышленности (при производстве химических веществ 1 и 2 классов опасности).'),
('15', '15. Деятельность, связанная с добычей угля подземным способом.'),
('16', '16. Деятельность, связанная с эксплуатацией, ремонтом скважин и установок при переработке высокосернистой нефти, очистке нефти и газа от сероводорода, очистке нефтеналивных судов, цистерн, резервуаров, добычей и обработкой озокерита, экстракционноозокеритовым производством.'),
('17', '17. Деятельность, непосредственно связанная с контактами с возбудителями инфекционных заболеваний - патогенными микроорганизмами I и II группы патогенности, возбудителями особо опасных инфекций, а также с биологическими токсинами (микробного, растительного и животного происхождения) или с доступом к указанным субстанциям.');